import{_ as t,a as r,o as n,a6 as o}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Reopen a Return","description":"","frontmatter":{"outline":false,"examples":[{"id":"reopen-return","title":"Reopen a Return","description":"Reopen a canceled or declined return (RMA) request back to pending.","query":"mutation ReopenCustomerReturn($id: ID!) {\\n  reopenCustomerReturn(input: { id: $id }) {\\n    customerReturn {\\n      _id\\n      orderId\\n      orderIncrementId\\n      statusId\\n      statusTitle\\n      statusColor\\n      canClose\\n      canReopen\\n      isExpired\\n      messagesCount\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/shop/returns/12\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"reopenCustomerReturn\\": {\\n      \\"customerReturn\\": {\\n        \\"_id\\": 12,\\n        \\"orderId\\": 45,\\n        \\"orderIncrementId\\": \\"000000045\\",\\n        \\"statusId\\": 1,\\n        \\"statusTitle\\": \\"Pending\\",\\n        \\"statusColor\\": \\"#FDB022\\",\\n        \\"canClose\\": true,\\n        \\"canReopen\\": false,\\n        \\"isExpired\\": false,\\n        \\"messagesCount\\": 2,\\n        \\"updatedAt\\": \\"2026-07-20T11:05:00+00:00\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"reopen not allowed","cause":"The store's settings do not allow reopening returns","solution":"Reopening must be enabled in the store's admin configuration"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"NOT_FOUND","cause":"The return does not exist or is not owned by the authenticated customer","solution":"Only return IDs belonging to the logged-in customer can be reopened"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/returns/mutations/reopen-return.md","filePath":"api/graphql-api/shop/returns/mutations/reopen-return.md","lastUpdated":1787725411000}`),d={name:"api/graphql-api/shop/returns/mutations/reopen-return.md"};function a(s,e,i,u,c,l){return n(),r("div",null,e[0]||(e[0]=[o('<h1 id="reopen-a-return" tabindex="-1">Reopen a Return <a class="header-anchor" href="#reopen-a-return" aria-label="Permalink to &quot;Reopen a Return&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>reopenCustomerReturn</code> mutation reopens a canceled or declined return (RMA) request back to <code>Pending</code> — but only when the store&#39;s settings allow customers to reopen returns. If reopening is disabled, the mutation fails. The result carries the updated return.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This mutation requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>✅ Yes</td><td>The return IRI, e.g. <code>/api/shop/returns/12</code>.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>customerReturn._id</code></td><td><code>Int!</code></td><td>Numeric return ID.</td></tr><tr><td><code>customerReturn.orderId</code></td><td><code>Int!</code></td><td>Id of the order the item belongs to.</td></tr><tr><td><code>customerReturn.orderIncrementId</code></td><td><code>String!</code></td><td>Human-readable order number.</td></tr><tr><td><code>customerReturn.statusId</code></td><td><code>Int!</code></td><td>Numeric status id after the reopen — <code>1</code> (Pending).</td></tr><tr><td><code>customerReturn.statusTitle</code></td><td><code>String!</code></td><td>Status label.</td></tr><tr><td><code>customerReturn.statusColor</code></td><td><code>String!</code></td><td>Hex color for the status badge.</td></tr><tr><td><code>customerReturn.canClose</code></td><td><code>Boolean</code></td><td>Whether the return can be closed.</td></tr><tr><td><code>customerReturn.canReopen</code></td><td><code>Boolean</code></td><td>Whether the return can be reopened.</td></tr><tr><td><code>customerReturn.isExpired</code></td><td><code>Boolean</code></td><td>Whether the return is past its action window.</td></tr><tr><td><code>customerReturn.messagesCount</code></td><td><code>Int!</code></td><td>Number of conversation messages on the return.</td></tr><tr><td><code>customerReturn.updatedAt</code></td><td><code>DateTime!</code></td><td>Return last update timestamp.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/returns/mutations/cancel-return.html">Cancel a Return</a></li><li><a href="/api/graphql-api/shop/returns/mutations/close-return.html">Close a Return</a></li><li><a href="/api/graphql-api/shop/returns/">Returns Overview</a></li></ul>',11)]))}const m=t(d,[["render",a]]);export{p as __pageData,m as default};
